dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "gene",
      "label": "Search gene",
      "type": "input",
      "values": "kp genes"
    }
  ],
  "sections": [
    {
      "section id": "upper_section",
      "header": "MATKP gene signatures",
      "data point": {
        "type": "bioindex",
        "url": "https://matkp.hugeampkpnbi.org/api/bio/",
        "index": "single-cell-gene",
        "parameters": [
          "gene"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene"
          },
          {
            "type": "raw",
            "field name": "Signature",
            "raw field": "datasetRef"
          },
          {
            "type": "raw",
            "field name": "Species",
            "raw field": "species"
          },
          {
            "type": "raw",
            "field name": "Log Fold Change",
            "raw field": "log_fold_change"
          },
          {
            "type": "raw",
            "field name": "P-value",
            "raw field": "p_value"
          },
          {
            "type": "raw",
            "field name": "P-value(adj)",
            "raw field": "p_value_adj"
          },
          {
            "type": "raw",
            "field name": "Data Type",
            "raw field": "datasetType"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "datasetId"
          },
          {
            "type": "join",
            "field name": "Signature/Dataset",
            "fields to join": [
              "datasetRef",
              "datasetId"
            ],
            "join by": "-"
          },
          {
            "type": "calculate",
            "field name": "-log10(P)",
            "raw field": "p_value",
            "calculation type": "-log10"
          }
        ],
        "top rows": [
          "Signature",
          "Species",
          "Gene",
          "Log Fold Change",
          "P-value",
          "P-value(adj)",
          "Data Type",
          "Dataset"
        ],
        "column formatting": {
          "Dataset": {
            "type": [
              "link with parameters"
            ],
            "link to": "https://matkp.org/cellbrowser.html?",
            "parameters": {
              "datasetId": "Dataset",
              "gene": "Gene"
            }
          }
        }
      },
      "visualizer": {
        "label": "PPA",
        "type": "phewas plot",
        "group by": "Dataset",
        "y axis field": "-log10(P)",
        "convert y -log10": null,
        "y ticks decimal point": "2",
        "render by": "Signature",
        "y axis label": "-log10(P)",
        "x axis label": "Dataset",
        "beta field": "Log Fold Change",
        "hover content": [
          "Signature",
          "Species",
          "Log Fold Change",
          "P-value",
          "P-value(adj)",
          "Data Type",
          "Dataset"
        ],
        "thresholds": [
          2
        ],
        "label in black": "greater than",
        "height": 400,
        "plot margin": {
          "top": 250,
          "bottom": 250,
          "left": 150,
          "right": 150
        }
      }
    },
    {
      "section id": "lower_section",
      "header": "Section to add the images from MATKP / ATKP",
      "data point": {
        "type": "bioindex",
        "url": "dummy",
        "index": "dummy",
        "parameters": [
          "phenotype"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
      }
    }
  ]
}

pageStyle:
*{box-sizing:border-box;}
       body{font-family:Arial, Helvetica, sans-serif; margin:0; padding:0}
       .f-row{display:flex;}
       .f-col{display:flex;flex-direction:column;}
       .f-row.v-center{align-items:center;}
       .f-row.h-center{justify-content:center;}
       .f-col.h-center{align-items: center;}
       .grow{flex:1;}
       .logo{max-width:300px;}
       .plot-title{font-size:20px;font-weight:bold;letter-spacing:-0.3px; border-radius: 20px;}
       .block{padding: 20px; box-shadow: rgba(0, 0, 0, 0.1) 0px 10px 15px -3px, rgba(0, 0, 0, 0.05) 0px 4px 6px -2px;}
       .bg{background: linear-gradient(180deg, gold, transparent);}

       .dataset-page-header{display:none}
       .paper-footer-wrapper{display:none;}
       .col-md-12{padding:0;}
       .card-body{padding:0;}
       .mdkp-card{margin:0}
       .mdkp-body{padding:0;}
       .kp-tabs-contents, .card.mdkp-card, .multi-section{border: none !important;}
      div.research-header-menu-wrapper.container-fluid.research-portal-header{display:none !important;}
      div.row.section-header{display:none !important;}
      div#section_upper_section{padding: 0 150px;}
      div#searchCriteria{background-color: transparent; border:none;}
      div#searchCriteria.fixed-header{background-color: #ddefff;border: solid 1px #bbdfff;}
      .card-title{display:none}
      div#searchCriteria input{width:740px; height: 45px; border:2px solid #3b3b3b; background: #eee; font-size: 16px; padding:10px; border-radius: 10px;}
